"""Complete forty original sepsis questions with adjuncts and recovery."""
from create_sepsis_infection_control import rows,q,SS,S3,CO
from qbank_authoring import finalize
q('A patient has septic shock with an ongoing vasopressor requirement after appropriate resuscitation. Which corticosteroid approach is consistent with current guidance?', 'Consider intravenous corticosteroids, commonly hydrocortisone about 200 mg/day in a protocolized regimen',[
 ('Pulse hydrocortisone above 400 mg/day for fewer than three days as routine treatment','High-dose short-duration treatment is recommended against.'),('Give steroids to every uncomplicated infection regardless of shock','This is not the septic-shock recommendation.'),('Wait for a diagnostic ACTH stimulation test before every shock-treatment decision','Routine testing is not required to select this adjunct in the usual pathway.')],
 'Corticosteroids are an adjunct to shock management', '**SSC 2026 suggests IV corticosteroids for septic shock.**',['Hydrocortisone-based regimens are commonly used.','They do not replace antibiotics, source control or vasopressors.'], '**Monitor adverse effects and response.**',['Hyperglycemia and neuromuscular effects require attention.','Avoid confusing low-dose adjunctive treatment with high-dose pulse regimens.'],[['Setting','Septic shock'],['Common regimen','Hydrocortisone around 200 mg/day'],['Avoid','Routine high-dose short-course pulse strategy']],[SS,CO],style='clinical_scenario')
q('A patient with septic shock has pH 7.15 and stage 2 acute kidney injury. Which bicarbonate statement best reflects SSC guidance?', 'Bicarbonate may be considered for this severe metabolic acidemia with significant AKI',[
 ('It is mandatory for every lactate above 2 regardless of pH or kidney function','A lactate rise alone is not the indication.'),('It directly treats the infection and eliminates the need for source control','It does not.'),('It is categorically prohibited in every septic patient with acidemia','The guideline identifies a selected severe-acidemia/AKI context.')],
 'The indication depends on the acidemia and renal context', '**SSC suggests bicarbonate when pH is ≤7.2 with AKIN stage 2 or 3.**',['This differs from routine bicarbonate solely to improve vasopressor response in lactic acidemia.','Sodium load, carbon dioxide generation and ionized calcium effects matter.'], '**Treat the underlying shock and assess renal support indications.**',['Monitor blood gases and electrolytes.','Do not let buffer treatment delay definitive management.'],[['Selected context','Severe acidemia plus significant AKI'],['Not routine','Lactate elevation alone'],['Monitoring','Gas exchange, sodium and ionized calcium']],[SS],style='clinical_scenario')
q('A septic patient has AKI but no refractory hyperkalemia, severe uncontrolled acidemia, pulmonary edema or other definitive indication for dialysis. Which approach is suggested?', 'Do not initiate renal replacement therapy solely because AKI is present; monitor closely for indications',[
 ('Dialyze every patient immediately at the first creatinine rise','This can expose patients to unnecessary invasive treatment.'),('Never use dialysis in sepsis even if refractory indications develop','Life-threatening indications still require treatment.'),('Use creatinine alone to determine all dialysis decisions','Clinical context and complications matter.')],
 'AKI staging and an immediate renal-support indication are different concepts', '**Sepsis-associated AKI can recover with appropriate causal and supportive treatment.**',['Track urine output, electrolytes, acid-base state and volume.','Avoid nephrotoxins and adjust drug dosing.'], '**Initiate support when a definitive indication develops.**',['Continuous or intermittent modalities can be used according to circumstances.','Hemodynamic stability and local resources influence modality selection.'],[['AKI alone','Not an automatic RRT trigger'],['Complications','Can require urgent support'],['Modality','Patient and resource dependent']],[SS])
q('A septic patient is not bleeding, has no acute myocardial ischemia and is otherwise stabilized. Which transfusion principle is recommended?', 'Use a restrictive RBC strategy with clinical assessment rather than routine liberal transfusion',[
 ('Normalize every hemoglobin to 12 g/dL','Routine normalization is not the goal.'),('Give plasma instead of RBCs for oxygen delivery','Plasma does not provide red-cell oxygen-carrying capacity.'),('Never transfuse RBCs in sepsis even with a compelling indication','Selected patients still need transfusion.')],
 'More donor blood does not automatically improve oxygen utilization', '**SSC favors a restrictive over a liberal RBC strategy in sepsis.**',['A threshold around 7 g/dL is commonly used in suitable stable adults.','Active hemorrhage, ischemia and severe hypoxemia require individualized decisions.'], '**Assess the patient rather than the concentration alone.**',['Consider trajectory, symptoms and transfusion risk.','Treat the cause of anemia when possible.'],[['Stable context','Restrictive strategy'],['Special circumstances','Individualize'],['Goal','Adequate clinical oxygen delivery']],[SS])
q('At what glucose level does the 2026 SSC recommend initiating insulin therapy in adults with sepsis or septic shock?', 'At least 180 mg/dL (10 mmol/L)',[
 ('At 90 mg/dL to force a normal fasting concentration','Tight normal-range control increases hypoglycemia risk.'),('Only above 400 mg/dL in every patient','This delays treatment of clinically important hyperglycemia.'),('Never use insulin during septic shock','Insulin is used with appropriate monitoring.')],
 'Avoid both uncontrolled hyperglycemia and treatment-induced hypoglycemia', '**The initiation threshold is ≥180 mg/dL.**',['Use the institutional critical-care insulin protocol.','Nutrition, steroids and renal function can change insulin needs.'], '**Monitor glucose frequently during changing physiology.**',['Do not pursue tight fasting-normal values routinely.','Ensure a response plan for hypoglycemia and interrupted feeding.'],[['Initiation','≥180 mg/dL'],['Safety','Avoid hypoglycemia'],['Adjustment','Changing nutrition and organ function']],[SS])
q('Which statement about high-dose IV vitamin C as routine sepsis treatment is correct?', 'Current SSC guidance suggests against its routine use',[
 ('It is a mandatory component of every shock bundle','It is not recommended as a routine adjunct.'),('It substitutes for adequate antimicrobial therapy','It does not treat the source or replace antimicrobials.'),('It has established survival benefit sufficient to override all contraindications','The evidence does not support that claim.')],
 'Biological plausibility does not establish clinical benefit', '**SSC 2026 suggests against IV vitamin C for sepsis or septic shock.**',['This is separate from treating a documented nutritional deficiency.','Other unproven adjuncts also require evidence rather than mechanistic appeal alone.'], '**Prioritize interventions with established roles.**',['Timely infection treatment and individualized resuscitation remain central.','Check adverse effects and interactions of any adjunct under consideration.'],[['Routine high-dose IV vitamin C','Not suggested'],['Deficiency treatment','Separate indication'],['Priority','Source treatment and organ support']],[SS])
q('A patient recovering from septic shock is hemodynamically suitable for enteral feeding. What timing does the 2026 SSC suggest?', 'Early enteral nutrition within 72 hours when feasible',[
 ('Withhold all enteral nutrition for at least two weeks in every case','Prolonged routine fasting is not recommended.'),('Force full feeding during uncontrolled shock regardless of tolerance','Perfusion and feeding tolerance must be assessed.'),('Use parenteral nutrition automatically even when the gut is usable','A functioning gastrointestinal tract supports an enteral strategy when appropriate.')],
 'Nutrition is part of supportive care after immediate threats are addressed', '**Early enteral feeding is suggested when feasible.**',['Shock severity and gastrointestinal tolerance affect the plan.','Begin and advance according to the clinical and nutrition protocol.'], '**Monitor for complications and changing tolerance.**',['Uncontrolled shock is different from a stabilized patient on an improving trajectory.','Avoid overfeeding and coordinate glucose management.'],[['Timing','Within 72 hours when feasible'],['Route','Enteral if suitable'],['Safety','Perfusion and tolerance assessment']],[SS],style='clinical_scenario')
q('A septic inpatient has elevated VTE risk and no bleeding contraindication. Which preventive approach is recommended?', 'Pharmacological prophylaxis, generally preferring LMWH over UFH when appropriate',[
 ('No prophylaxis because sepsis-associated thrombocytopenia always prevents thrombosis','Sepsis can remain prothrombotic.'),('Therapeutic-dose anticoagulation for every patient solely because sepsis is present','Treatment dosing needs a separate indication.'),('Aspirin as a universal substitute for standard medical VTE prophylaxis','This is not the recommended sepsis prevention approach.')],
 'Critical illness combines immobility and prothrombotic inflammation', '**SSC recommends pharmacological prophylaxis unless contraindicated.**',['LMWH is generally preferred to UFH.','Renal impairment, bleeding and procedures can modify selection.'], '**Reassess daily as the clinical state changes.**',['Mechanical methods can be considered when medication is unsafe.','Do not confuse prophylaxis with treatment of established VTE.'],[['No contraindication','Pharmacological prophylaxis'],['Common preference','LMWH'],['Changing risk','Reassess bleeding, renal function and procedures']],[SS])
q('After septic shock has resolved, a patient has substantial positive fluid balance, edema and improving hemodynamics. Which strategy may be appropriate?', 'Consider active fluid removal after the acute resuscitation phase, based on clinical tolerance',[
 ('Continue resuscitation boluses solely because shock occurred earlier','The phase of illness has changed.'),('Use aggressive fluid removal during escalating shock regardless of perfusion','Removal must be matched to hemodynamic tolerance.'),('Ignore fluid balance because edema is only cosmetic','Congestion can impair organ function.')],
 'Fluid management changes across the illness course', '**SSC 2026 suggests active removal after acute resuscitation.**',['Diuretics or extracorporeal removal may be used according to need.','Cardiorespiratory function, vasopressor course and fluid balance guide timing.'], '**Monitor perfusion and organ response during removal.**',['Adjust or pause if hypotension or hypoperfusion develops.','The target is clinically appropriate decongestion rather than an arbitrary negative balance.'],[['Resuscitation','Restore effective circulation'],['Recovery','Assess accumulated congestion'],['Removal','Individualized and monitored']],[SS],style='clinical_scenario')
q('A sepsis survivor reports new weakness, memory difficulties and anxiety after discharge. What is the best follow-up principle?', 'Assess physical, cognitive and mental-health sequelae and arrange appropriate rehabilitation and follow-up',[
 ('Dismiss symptoms because cultures became negative in hospital','Infection resolution does not exclude post-sepsis impairment.'),('Restart broad antibiotics automatically for every persistent symptom','Reinfection needs assessment, but these symptoms are not proof of it.'),('Limit follow-up to the original infection site alone','Recovery can involve several domains.')],
 'Sepsis can have consequences beyond the acute infection', '**Survivors may experience new or worsened functional and psychological difficulties.**',['Reconcile medicines and review ongoing treatment needs.','Explain warning signs for recurrent illness and the recovery plan.'], '**Coordinate primary and specialist care.**',['Refer for rehabilitation or mental-health evaluation when indicated.','Include the patient and family in realistic goals and support planning.'],[['Physical','Weakness and functional loss'],['Cognitive','Memory and attention concerns'],['Psychological','Anxiety, depression or trauma-related symptoms']],[SS],style='clinical_scenario')

if __name__=='__main__':finalize('Infectious disease',2,'Sepsis and Septic Shock','id-sepsis',rows,40)
